long long inv=0;
vector<int> ms(vector<int>& a,int l,int r){
    if(l==r)return {a[l]};
    int m=(l+r)/2;
    auto L=ms(a,l,m),R=ms(a,m+1,r);
    vector<int>res;
    int i=0,j=0;
    while(i<(int)L.size()&&j<(int)R.size()){
        if(L[i]<=R[j])res.push_back(L[i++]);
        else{res.push_back(R[j++]);inv+=L.size()-i;}
    }
    while(i<(int)L.size())res.push_back(L[i++]);
    while(j<(int)R.size())res.push_back(R[j++]);
    return res;
}
int main(){
    int n;cin>>n;
    vector<int>a(n);
    for(int i=0;i<n;i++)cin>>a[i];
    ms(a,0,n-1);
    cout<<inv<<'\n';
}

