vector<int> multiply(vector<int>& res, int x){
    int carry=0;
    for(int i=0;i<(int)res.size();i++){
        int prod=res[i]*x+carry;
        res[i]=prod%10;
        carry=prod/10;
    }
    while(carry){res.push_back(carry%10);carry/=10;}
    return res;
}
int main(){
    int n;cin>>n;
    vector<int>res={1};
    for(int i=2;i<=n;i++)multiply(res,i);
    for(int i=res.size()-1;i>=0;i--)cout<<res[i];
    cout<<'\n';
}

