                st = new StringTokenizer(line);
            }
            if (!st.hasMoreTokens()) break;
            arr[ptr++] = Long.parseLong(st.nextToken());
        }
        int low = 0, high = M * N - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (arr[mid] == K) {
                int r = mid / N;
                int c = mid % N;
                System.out.println("FOUND " + r + " " + c);
                return;
            } else if (arr[mid] < K) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        System.out.println("NOT_FOUND");
    }
}

