        int minVal = Integer.MAX_VALUE, maxVal = Integer.MIN_VALUE;
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                while (!st.hasMoreTokens()) {
                    line = br.readLine();
                    if (line == null) break;
                    st = new StringTokenizer(line);
                }
                grid[r][c] = Integer.parseInt(st.nextToken());
            }
            minVal = Math.min(minVal, grid[r][0]);
            maxVal = Math.max(maxVal, grid[r][C - 1]);
        }
        int desired = (R * C + 1) / 2;
        int low = minVal, high = maxVal;
        while (low < high) {
            int mid = low + (high - low) / 2;
            int count = 0;
            for (int r = 0; r < R; r++) {
                count += upperBound(grid[r], mid);
            }
            if (count < desired) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        System.out.println(low);
    }
    private static int upperBound(int[] row, int target) {
        int l = 0, r = row.length;
        while (l < r) {
            int m = (l + r) / 2;
            if (row[m] <= target) l = m + 1;
            else r = m;
        }
        return l;
    }
}

