    S, P = lines[0], lines[1]
    n, m = len(S), len(P)
    if m > n:
        print('NOT_FOUND')
        return
    lps = compute_lps(P)
    res = []
    i = j = 0
    while i < n:
        if P[j] == S[i]:
            i += 1; j += 1
        if j == m:
            res.append(str(i - j))
            j = lps[j - 1]
        elif i < n and P[j] != S[i]:
