    static int findBound(int[] a, int T, boolean isFirst) {
        int l = 0, r = a.length - 1, ans = -1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (a[mid] == T) {
                ans = mid;
                if (isFirst) r = mid - 1;
                else l = mid + 1;
            } else if (a[mid] < T) l = mid + 1;
            else r = mid - 1;
        }
        return ans;
    }
