    static long count = 0;
    static long[] mergeSort(long[] arr, int l, int r) {
        if (l >= r) return new long[]{arr[l]};
        int mid = (l + r) / 2;
        long[] L = mergeSort(arr, l, mid);
        long[] R = mergeSort(arr, mid+1, r);
        long[] res = new long[L.length + R.length];
        int i = 0, j = 0, k = 0;
        while (i < L.length && j < R.length) {
            if (L[i] <= R[j]) res[k++] = L[i++];
            else { res[k++] = R[j++]; count += L.length - i; }
        }
        while (i < L.length) res[k++] = L[i++];
        while (j < R.length) res[k++] = R[j++];
        return res;
    }
    public static void main(String[] args) throws IOException {
