int query(int idx) {
    int s = 0;
    for (; idx > 0; idx -= idx & (-idx)) s += bit[idx];
    return s;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    if (!(cin >> N)) return 0;
    vector<int> arr(N), sorted_arr(N);
    for (int i = 0; i < N; i++) { cin >> arr[i]; sorted_arr[i] = arr[i]; }
    sort(sorted_arr.begin(), sorted_arr.end());
    bit.assign(N + 2, 0);
    long long inversions = 0;
    for (int i = 0; i < N; i++) {
        int rank = lower_bound(sorted_arr.begin(), sorted_arr.end(), arr[i]) - sorted_arr.begin() + 1;
        inversions += i - query(rank);
        add(rank, 1);
    }
    cout << inversions << "\n";
    return 0;
}

