import heapq

def solve():
    data = sys.stdin.read().split()
    idx = 0
    N, M, S = int(data[idx]), int(data[idx+1]), int(data[idx+2]); idx += 3
    adj = [[] for _ in range(N+1)]
    for _ in range(M):
        u,v,w = int(data[idx]),int(data[idx+1]),int(data[idx+2]); idx+=3
        adj[u].append((v,w)); adj[v].append((u,w))
    INF = float('inf'); dist = [INF]*(N+1); dist[S] = 0
    heap = [(0, S)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]: continue
        for v, w in adj[u]:
            if dist[u]+w < dist[v]: dist[v]=dist[u]+w; heapq.heappush(heap,(dist[v],v))
    for i in range(1, N+1): print(-1 if dist[i]==INF else dist[i])

if __name__ == '__main__':
    solve()

