public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken()), M = Integer.parseInt(st.nextToken()), S = Integer.parseInt(st.nextToken());
        List<long[]>[] adj = new List[N+1];
        for (int i = 0; i <= N; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            long u=Long.parseLong(st.nextToken()),v=Long.parseLong(st.nextToken()),w=Long.parseLong(st.nextToken());
            adj[(int)u].add(new long[]{v,w}); adj[(int)v].add(new long[]{u,w});
        }
        long[] dist = new long[N+1]; Arrays.fill(dist, Long.MAX_VALUE); dist[S] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a->a[0]));
        pq.offer(new long[]{0, S});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll(); long d = cur[0]; int u = (int)cur[1];
            if (d > dist[u]) continue;
            for (long[] e : adj[u]) { int v=(int)e[0]; long w=e[1];
                if (dist[u]+w < dist[v]) { dist[v]=dist[u]+w; pq.offer(new long[]{dist[v],v}); }
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= N; i++) sb.append(dist[i]==Long.MAX_VALUE?-1:dist[i]).append('\n');
        System.out.print(sb);
    }
}

