            for (int v : adj.get(u)) { indegree[v]--; if (indegree[v]==0) q.offer(v); }
        }
        if (order.size() == N) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < N; i++) { if(i>0)sb.append(' '); sb.append(order.get(i)); }
            System.out.println(sb);
        } else System.out.println("IMPOSSIBLE");
    }
}

