            st = new StringTokenizer(br.readLine());
            edges[i][0]=Long.parseLong(st.nextToken());edges[i][1]=Long.parseLong(st.nextToken());edges[i][2]=Long.parseLong(st.nextToken());
        }
        Arrays.sort(edges, Comparator.comparingLong(a->a[2]));
        parent=new int[N+1]; rnk=new int[N+1];
        for(int i=0;i<=N;i++) parent[i]=i;
        long total=0; int cnt=0;
        for (long[] e : edges) {
            if (union((int)e[0],(int)e[1])) { total+=e[2]; cnt++; if(cnt==N-1)break; }
