import sys
from collections import deque

def solve():
    lines = sys.stdin.read().split('\n')
    idx = 0
    W, K = map(int, lines[idx].split()); idx += 1
    words = [lines[idx+i].strip() for i in range(W)]; idx += W
    chars = [chr(ord('a')+i) for i in range(K)]
    char_idx = {c: i for i, c in enumerate(chars)}
    adj = [[] for _ in range(K)]; indegree = [0]*K
    valid = True
    for i in range(len(words)-1):
        w1, w2 = words[i], words[i+1]; found = False
        for c1, c2 in zip(w1, w2):
            if c1 != c2:
                a, b = char_idx.get(c1, -1), char_idx.get(c2, -1)
                if a == -1 or b == -1: break
                adj[a].append(b); indegree[b] += 1; found = True; break
        if not found and len(w1) > len(w2): valid = False; break
    if not valid: print('INVALID'); return
    queue = deque(i for i in range(K) if indegree[i] == 0)
    order = []
    while queue:
        u = queue.popleft(); order.append(chars[u])
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0: queue.append(v)
    if len(order) == K: print(''.join(order))
    else: print('INVALID')

if __name__ == '__main__':
    solve()

