        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        int N = Integer.parseInt(line.trim());
        List<Integer>[] adj = new List[N + 1];
        for (int i = 0; i <= N; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < N - 1; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()), v = Integer.parseInt(st.nextToken());
            adj[u].add(v); adj[v].add(u);
        }
        tin = new int[N + 1]; tout = new int[N + 1];
        ArrayDeque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{1, 0, 0});
        while (!stack.isEmpty()) {
            int[] top = stack.pop();
            int u = top[0], p = top[1], state = top[2];
            if (state == 1) {
                tout[u] = ++timer;
            } else {
                tin[u] = ++timer;
                stack.push(new int[]{u, p, 1});
                for (int v : adj[u]) {
                    if (v != p) stack.push(new int[]{v, u, 0});
                }
            }
        }
        int Q = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();
        for (int q = 0; q < Q; q++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int t = Integer.parseInt(st.nextToken()), u = Integer.parseInt(st.nextToken()), v = Integer.parseInt(st.nextToken());
            boolean ok = (t == 0) ? (tin[u] <= tin[v] && tout[u] >= tout[v]) : (tin[v] <= tin[u] && tout[v] >= tout[u]);
            sb.append(ok ? "YES\n" : "NO\n");
        }
        System.out.print(sb);
    }
}

