def solve():
    input_data = sys.stdin.read().split()
    if not input_data: return
    N, M = int(input_data[0]), int(input_data[1])
    if M == 0:
        print('CYCLE'); return

    adj = [[] for _ in range(N + 1)]
    deg = [0] * (N + 1)
    idx = 2
    start_node = -1
    for _ in range(M):
        u, v = int(input_data[idx]), int(input_data[idx+1]); idx += 2
        adj[u].append(v); adj[v].append(u)
        deg[u] += 1; deg[v] += 1
        start_node = u

    # Check connectivity of vertices with degree > 0
    visited = [False] * (N + 1)
    stack = [start_node]
    visited[start_node] = True
    while stack:
        curr = stack.pop()
        for nxt in adj[curr]:
            if not visited[nxt]:
                visited[nxt] = True
                stack.append(nxt)

    for i in range(1, N + 1):
        if deg[i] > 0 and not visited[i]:
            print('IMPOSSIBLE'); return

    odd_count = sum(1 for i in range(1, N + 1) if deg[i] % 2 != 0)
    if odd_count == 0:
        print('CYCLE')
    elif odd_count == 2:
        print('PATH')
    else:
        print('IMPOSSIBLE')

