vector<long long> memo;

long long minMatching(int mask) {
    if (mask == 0) return 0;
    if (memo[mask] != -1) return memo[mask];
    int first = -1;
    for (int i = 0; i < K; i++) if (mask & (1 << i)) { first = i; break; }
    long long res = 1e18;
