import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data: return
    N, M = int(input_data[0]), int(input_data[1])
    if N <= 2:
        print('POSSIBLE'); return

    adj_matrix = [[False] * (N + 1) for _ in range(N + 1)]
    idx = 2
    for _ in range(M):
        u = int(input_data[idx]); v = int(input_data[idx+1]); idx += 2
        adj_matrix[u][v] = True
        adj_matrix[v][u] = True

    # Build complement graph: edge if NOT connected in original
    comp_adj = [[] for _ in range(N + 1)]
    for i in range(1, N + 1):
        for j in range(i + 1, N + 1):
            if not adj_matrix[i][j]:
                comp_adj[i].append(j)
                comp_adj[j].append(i)

    # Check if complement graph is bipartite
    color = [0] * (N + 1)
    for start in range(1, N + 1):
        if color[start] == 0:
            color[start] = 1
            queue = deque([start])
            while queue:
                u = queue.popleft()
                for v in comp_adj[u]:
                    if color[v] == 0:
                        color[v] = 3 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        print('IMPOSSIBLE'); return

    print('POSSIBLE')

if __name__ == '__main__':
    solve()

