public class Main {
    static class Node {
        String val;
        Node left, right;
        Node(String v) { this.val = v; }
    }
    static int idx = 0;
    static Node parseNode(String s) {
        if (idx >= s.length() || s.charAt(idx) == ')') return null;
        int start = idx;
        while (idx < s.length() && s.charAt(idx) != '(' && s.charAt(idx) != ')') {
            idx++;
        }
        Node node = new Node(s.substring(start, idx));
        if (idx < s.length() && s.charAt(idx) == '(') {
            idx++;
            node.left = parseNode(s);
            if (idx < s.length() && s.charAt(idx) == ')') idx++;
        }
        if (idx < s.length() && s.charAt(idx) == '(') {
            idx++;
            node.right = parseNode(s);
            if (idx < s.length() && s.charAt(idx) == ')') idx++;
        }
        return node;
    }
    static void preorder(Node node, List<String> res) {
        if (node == null) return;
