Node* parseNode(const string& s, size_t& idx) {
    if (idx >= s.length() || s[idx] == ')') return nullptr;
    size_t start = idx;
    while (idx < s.length() && s[idx] != '(' && s[idx] != ')') {
        idx++;
    }
    Node* node = new Node(s.substr(start, idx - start));
    if (idx < s.length() && s[idx] == '(') {
