        node->left = parseNode(s, idx);
        if (idx < s.length() && s[idx] == ')') idx++;
    }
    if (idx < s.length() && s[idx] == '(') {
        idx++;
        node->right = parseNode(s, idx);
        if (idx < s.length() && s[idx] == ')') idx++;
    }
    return node;
}

