from collections import deque

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build_tree(tokens):
    if not tokens or tokens[0] == 'null': return None
    root = Node(tokens[0])
    q = deque([root])
    i = 1
    while q and i < len(tokens):
        curr = q.popleft()
        if i < len(tokens) and tokens[i] != 'null':
            curr.left = Node(tokens[i])
            q.append(curr.left)
        i += 1
        if i < len(tokens) and tokens[i] != 'null':
            curr.right = Node(tokens[i])
            q.append(curr.right)
        i += 1
    return root

def solve():
    tokens = sys.stdin.read().split()
    root = build_tree(tokens)
    if not root:
        print('true'); return
    leaf_level = None
    q = deque([(root, 0)])
