using namespace std;

struct Node {
    long long val;
    Node *left = nullptr, *right = nullptr;
    Node(long long v) : val(v) {}
};

Node* buildTree(const vector<string>& tokens) {
    if (tokens.empty() || tokens[0] == "null") return nullptr;
    Node* root = new Node(stoll(tokens[0]));
    queue<Node*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < tokens.size()) {
        Node* curr = q.front(); q.pop();
        if (i < tokens.size() && tokens[i] != "null") {
            curr->left = new Node(stoll(tokens[i]));
            q.push(curr->left);
        }
        i++;
        if (i < tokens.size() && tokens[i] != "null") {
            curr->right = new Node(stoll(tokens[i]));
            q.push(curr->right);
        }
        i++;
    }
    return root;
}

void inorder(Node* node, vector<long long>& arr) {
    if (!node) return;
    inorder(node->left, arr);
    arr.push_back(node->val);
    inorder(node->right, arr);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    string line1, line2;
    getline(cin, line1);
