    while (ss1 >> t) tokens1.push_back(t);
    while (ss2 >> t) tokens2.push_back(t);
    Node* t1 = buildTree(tokens1);
    Node* t2 = buildTree(tokens2);
    vector<long long> a1, a2;
    inorder(t1, a1);
    inorder(t2, a2);
    size_t i = 0, j = 0;
    bool first = true;
    while (i < a1.size() && j < a2.size()) {
        if (!first) cout << ' ';
        if (a1[i] <= a2[j]) cout << a1[i++];
        else cout << a2[j++];
        first = false;
    }
