    static int[][] grid = new int[9][9];
    static int[] rowUsed = new int[9];
    static int[] colUsed = new int[9];
    static int[] boxUsed = new int[9];
    static List<int[]> empty = new ArrayList<>();

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (!sc.hasNextInt()) return;
                grid[i][j] = sc.nextInt();
                int val = grid[i][j];
                if (val != 0) {
                    int mask = 1 << val;
                    rowUsed[i] |= mask;
                    colUsed[j] |= mask;
                    boxUsed[(i / 3) * 3 + (j / 3)] |= mask;
                } else {
                    empty.add(new int[]{i, j});
                }
            }
        }

        backtrack(0);
        for (int i = 0; i < 9; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < 9; j++) {
                if (j > 0) sb.append(" ");
                sb.append(grid[i][j]);
            }
            System.out.println(sb.toString());
        }
    }

    static boolean backtrack(int idx) {
        if (idx == empty.size()) return true;
        int r = empty.get(idx)[0];
        int c = empty.get(idx)[1];
        int b = (r / 3) * 3 + (c / 3);
        int used = rowUsed[r] | colUsed[c] | boxUsed[b];

        for (int val = 1; val <= 9; val++) {
            int mask = 1 << val;
            if ((used & mask) == 0) {
                grid[r][c] = val;
                rowUsed[r] |= mask;
                colUsed[c] |= mask;
                boxUsed[b] |= mask;

                if (backtrack(idx + 1)) return true;

                rowUsed[r] &= ~mask;
                colUsed[c] &= ~mask;
                boxUsed[b] &= ~mask;
                grid[r][c] = 0;
            }
        }
        return false;
    }
}

