import sys

def solve():
    raw = sys.stdin.read().split()
    if not raw:
        return
    N = int(raw[0])

    if N == 1:
        print(0)
        return
    if N in [2, 3, 4]:
        print("-1")
        return

    moves = [
        (2, 1), (1, 2), (-1, 2), (-2, 1),
        (-2, -1), (-1, -2), (1, -2), (2, -1)
    ]

    board = [[-1]*N for _ in range(N)]
    board[0][0] = 0

    def count_degree(r, c):
        cnt = 0
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N and board[nr][nc] == -1:
                cnt += 1
        return cnt

    def backtrack(r, c, step):
        if step == N * N:
            return True

        # Warnsdorff's heuristic: sort next moves by degree ascending
        next_moves = []
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N and board[nr][nc] == -1:
                deg = count_degree(nr, nc)
                next_moves.append((deg, nr, nc))

        next_moves.sort(key=lambda x: x[0])

        for deg, nr, nc in next_moves:
            board[nr][nc] = step
            if backtrack(nr, nc, step + 1):
                return True
            board[nr][nc] = -1

        return False

    if backtrack(0, 0, 1):
        for row in board:
            print(*(row))
    else:
        print("-1")

if __name__ == '__main__':
    solve()

