import sys

class DLLNode:
    def __init__(self, val):
        self.val = val
        self.prev = None
        self.next = None

class MidStack:
    def __init__(self):
        self.head = None
        self.mid = None
        self.count = 0

    def push(self, val):
        node = DLLNode(val)
        node.prev = None
        node.next = self.head
        self.count += 1

        if self.count == 1:
            self.head = node
            self.mid = node
        else:
            self.head.prev = node
            self.head = node
            # Move mid pointer when count becomes odd
            if self.count % 2 != 0:
                self.mid = self.mid.prev

    def pop(self):
        if self.count == 0:
            return -1
        val = self.head.val
        self.head = self.head.next
        if self.head:
            self.head.prev = None
        self.count -= 1

        if self.count == 0:
            self.mid = None
        elif self.count % 2 == 0:
            self.mid = self.mid.next

        return val

    def getMid(self):
        if self.count == 0 or not self.mid:
            return -1
        return self.mid.val

    def delMid(self):
        if self.count == 0 or not self.mid:
            return -1
        val = self.mid.val

        if self.count == 1:
            self.head = None
            self.mid = None
            self.count = 0
            return val

        prev_node = self.mid.prev
