                long x = Long.parseLong(st.nextToken());
                if (freeHead == -1) {
                    sb.append("-1\n");
                } else {
                    int idx = freeHead;
                    freeHead = next[idx];
                    next[idx] = top[s];
                    top[s] = idx;
                    arr[idx] = x;
