    static class Interval implements Comparable<Interval> {
        long s, e;
        Interval(long s, long e) { this.s = s; this.e = e; }
        public int compareTo(Interval o) {
            if (this.s != o.s) return Long.compare(this.s, o.s);
            return Long.compare(this.e, o.e);
        }
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        while (line != null && line.trim().isEmpty()) line = br.readLine();
        if (line == null) return;
        int N = Integer.parseInt(line.trim());

        List<Interval> list = new ArrayList<>();
        StringTokenizer st = null;
        for (int i = 0; i < N; i++) {
            while (st == null || !st.hasMoreTokens()) {
                line = br.readLine();
                if (line == null) break;
                st = new StringTokenizer(line);
            }
            long s = Long.parseLong(st.nextToken());
            long e = Long.parseLong(st.nextToken());
            list.add(new Interval(s, e));
        }
        Collections.sort(list);

        List<Interval> merged = new ArrayList<>();
        for (Interval iv : list) {
            if (merged.isEmpty() || iv.s > merged.get(merged.size() - 1).e) {
                merged.add(new Interval(iv.s, iv.e));
            } else {
                merged.get(merged.size() - 1).e = Math.max(merged.get(merged.size() - 1).e, iv.e);
            }
