class CircularQueue:
    def __init__(self, k):
        self.k = k
        self.arr = [0] * k
        self.head = 0
        self.count = 0

    def enQueue(self, val):
        if self.count == self.k:
            return -1
        tail = (self.head + self.count) % self.k
        self.arr[tail] = val
        self.count += 1
        return 1

