#include <iostream>
#include <vector>
#include <string>

using namespace std;

class CircularQueue {
    int k, head, count;
    vector<long long> arr;
public:
    CircularQueue(int k) : k(k), head(0), count(0), arr(k) {}

    int enQueue(long long val) {
        if (count == k) return -1;
        int tail = (head + count) % k;
        arr[tail] = val;
        count++;
        return 1;
    }
    int deQueue() {
        if (count == 0) return -1;
        head = (head + 1) % k;
        count--;
        return 1;
    }
    long long Front() {
        if (count == 0) return -1;
        return arr[head];
    }
    long long Rear() {
        if (count == 0) return -1;
        int tail = (head + count - 1) % k;
        return arr[tail];
    }
    int isEmpty() {
        return count == 0 ? 1 : 0;
    }
    int isFull() {
        return count == k ? 1 : 0;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int K, Q;
    if (!(cin >> K >> Q)) return 0;

    CircularQueue cq(K);
    while (Q--) {
        string cmd;
        cin >> cmd;
        if (cmd == "enQueue") {
            long long x; cin >> x;
            cout << cq.enQueue(x) << "\n";
        } else if (cmd == "deQueue") {
            cout << cq.deQueue() << "\n";
        } else if (cmd == "Front") {
            cout << cq.Front() << "\n";
        } else if (cmd == "Rear") {
            cout << cq.Rear() << "\n";
        } else if (cmd == "isEmpty") {
            cout << cq.isEmpty() << "\n";
        } else if (cmd == "isFull") {
            cout << cq.isFull() << "\n";
        }
    }
    return 0;
}

