import sys
from collections import OrderedDict

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return
    first = lines[0].strip().split()
    C = int(first[0])
    Q = int(first[1])

    cache = OrderedDict()
    out = []

    for i in range(1, Q + 1):
        if i >= len(lines):
            break
        parts = lines[i].strip().split()
        if not parts:
            continue
        cmd = parts[0]
        if cmd == "get":
            k = int(parts[1])
            if k in cache:
                cache.move_to_end(k)
                out.append(str(cache[k]))
            else:
                out.append("-1")
        elif cmd == "put":
            k = int(parts[1])
            v = int(parts[2])
            if k in cache:
                cache.move_to_end(k)
            elif len(cache) >= C:
                cache.popitem(last=False)
            cache[k] = v

    print('\n'.join(out))

if __name__ == '__main__':
