                long long val = it->second->second;
                lru.erase(it->second);
                lru.push_front({k, val});
                pos[k] = lru.begin();
                cout << val << "\n";
            }
        } else if (cmd == "put") {
            long long k, v; cin >> k >> v;
            auto it = pos.find(k);
            if (it != pos.end()) {
                lru.erase(it->second);
            } else if ((int)lru.size() >= C) {
                long long last_k = lru.back().first;
                lru.pop_back();
                pos.erase(last_k);
            }
            lru.push_front({k, v});
            pos[k] = lru.begin();
        }
    }
    return 0;
