struct Element {
    int count;
    char ch;
    bool operator<(const Element &o) const {
        if (count != o.count) return count < o.count; // max-heap
        return ch > o.ch; // tie-break: smaller char has higher priority
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string S;
    if (!(cin >> S)) return 0;
