    }

    if (maxFreq > (n + 1) / 2) {
        cout << "-1\n";
        return 0;
    }

    priority_queue<Element> pq;
    for (int i = 0; i < 26; i++) {
        if (freq[i] > 0) {
            pq.push({freq[i], (char)('a' + i)});
        }
    }

    string res = "";
    Element prev = {0, ' '};

    while (!pq.empty()) {
        Element cur = pq.top();
        pq.pop();
        res += cur.ch;
        cur.count--;

        if (prev.count > 0) {
            pq.push(prev);
        }
        prev = cur;
    }

