        self.val = val
        self.left = None
        self.right = None

def build_tree(vals):
    if not vals or vals[0] == -1:
        return None
    root = Node(vals[0])
    q = deque([root])
    idx = 1
    n = len(vals)

    while q and idx < n:
        cur = q.popleft()
        if idx < n:
            if vals[idx] != -1:
                cur.left = Node(vals[idx])
                q.append(cur.left)
            idx += 1
        if idx < n:
            if vals[idx] != -1:
                cur.right = Node(vals[idx])
                q.append(cur.right)
            idx += 1
    return root

def is_heap(root):
    if not root:
        return True

    q = deque([root])
    seen_null = False

    while q:
        cur = q.popleft()

        # Check left child
        if cur.left:
            if seen_null:
                return False
            if cur.left.val > cur.val:
                return False
            q.append(cur.left)
        else:
            seen_null = True

        # Check right child
        if cur.right:
            if seen_null:
                return False
            if cur.right.val > cur.val:
                return False
            q.append(cur.right)
        else:
