    Node(long long v) : val(v), left(nullptr), right(nullptr) {}
};

Node* buildTree(const vector<long long> &vals) {
    if (vals.empty() || vals[0] == -1) return nullptr;
    Node *root = new Node(vals[0]);
    queue<Node*> q;
    q.push(root);
    int idx = 1;
    int n = vals.size();

    while (!q.empty() && idx < n) {
        Node *cur = q.front();
        q.pop();

        if (idx < n) {
            if (vals[idx] != -1) {
                cur->left = new Node(vals[idx]);
                q.push(cur->left);
            }
            idx++;
        }
        if (idx < n) {
            if (vals[idx] != -1) {
                cur->right = new Node(vals[idx]);
                q.push(cur->right);
            }
            idx++;
        }
    }
    return root;
}

void inorder(Node *root, vector<long long> &arr) {
    if (!root) return;
    inorder(root->left, arr);
    arr.push_back(root->val);
    inorder(root->right, arr);
}

void bstToMinHeap(Node *root, const vector<long long> &arr, int &idx) {
    if (!root) return;
    root->val = arr[idx++];
    bstToMinHeap(root->left, arr, idx);
    bstToMinHeap(root->right, arr, idx);
}

void preorder(Node *root, vector<long long> &res) {
    if (!root) return;
    res.push_back(root->val);
    preorder(root->left, res);
    preorder(root->right, res);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    if (!(cin >> N)) return 0;
    vector<long long> vals(N);
    for (int i = 0; i < N; i++) cin >> vals[i];

    Node *root = buildTree(vals);
    if (!root) return 0;

    vector<long long> arr;
    inorder(root, arr);

    int idx = 0;
    bstToMinHeap(root, arr, idx);

    vector<long long> res;
    preorder(root, res);

    for (int i = 0; i < (int)res.size(); i++) {
        cout << res[i] << (i + 1 == (int)res.size() ? "" : " ");
    }
    cout << "\n";
    return 0;
}

