import sys

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        cur = self.root
        for ch in word:
            if ch not in cur.children:
                cur.children[ch] = TrieNode()
            cur = cur.children[ch]
        cur.is_end = True

    def find_all_with_prefix(self, prefix):
        cur = self.root
        for ch in prefix:
            if ch not in cur.children:
                return []
            cur = cur.children[ch]

        res = []
        def dfs(node, path):
            if node.is_end:
                res.append(''.join(path))
            for ch in sorted(node.children.keys()):
                path.append(ch)
                dfs(node.children[ch], path)
                path.pop()

        dfs(cur, list(prefix))
        return res

def solve():
