        }

        Collections.sort(subsets);

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < subsets.size(); i++) {
            if (i > 0) out.append(" ");
            out.append(subsets.get(i));
        }
        System.out.println(out.toString());
    }
}

